use codex_protocol::models::ExecutedToolCallArguments;
use codex_protocol::models::ResponseItem;
use codex_protocol::models::ToolResultMetadata;
use codex_protocol::models::bound_executed_tool_calls_for_prompt;
use codex_protocol::models::bound_executed_tool_calls_for_prompt_prioritizing_recent;
use codex_protocol::models::executed_tool_call_metadata_bytes;
use codex_protocol::openai_models::ToolMode;
use indexmap::IndexMap;
use serde_json::Value as JsonValue;
use tokio_util::sync::CancellationToken;

use crate::session::step_context::StepContext;
use crate::tools::context::ToolCallSource;
use crate::tools::context::ToolOutput;
use crate::tools::context::ToolPayload;
use crate::tools::metadata_metrics;
use crate::tools::router::ToolCall;
use crate::utils::json::serialized_json_bytes;

mod seen_ids;

use seen_ids::SeenIds;

const MAX_EXECUTED_TOOL_CALL_ARGUMENT_BYTES: usize = 8 * 1024;
const MAX_EXECUTED_TOOL_CALL_FULL_ARGUMENT_BYTES_PER_OUTPUT: usize = 32 * 1024;
const MAX_PENDING_EXECUTED_TOOL_CALLS: usize = 256;
// Limits new Direct metadata retained in history and the append-only rollout
// during one recorder lifetime. A new process cannot recover the exact prior
// budget because raw result metadata is intentionally not deserialized.
const MAX_RETAINED_DIRECT_METADATA_BYTES: usize = 1024 * 1024;

type ExecutedToolCallCache =
    HashMap<(std::mem::Discriminant<ResponseItem>, String), Vec<ExecutedToolCall>>;

/// Best-effort recording shared by a session and its Code Mode broker. Disabled
/// sessions allocate no recorder state; missing evidence remains incomplete.
#[derive(Clone, Default)]
pub(crate) struct ExecutedToolCalls {
    state: Arc<Mutex<Option<ExecutedToolCallRecorderState>>>,
    material_reset: Arc<Mutex<CancellationToken>>,
    retained_direct_metadata_bytes: Arc<AtomicUsize>,
    pending_direct_calls: Arc<AtomicUsize>,
    mcp_attribution: mcp_attribution::McpAttributionRecorder,
}

// Avoid exposing recorded call arguments or result metadata through client Debug output.
impl std::fmt::Debug for ExecutedToolCalls {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("ExecutedToolCalls")
            .finish_non_exhaustive()
    }
}

/// Checkpoint for this recorder's Option-state and genuine Direct reservation
/// and permit lifetimes. It does not cover MCP attribution or final request contributors.
#[derive(Clone)]
pub(crate) struct ExecutedToolCallsCheckpoint {
    state_owner: Weak<Mutex<Option<ExecutedToolCallRecorderState>>>,
    reset_owner: Weak<Mutex<CancellationToken>>,
    reset: CancellationToken,
}

#[derive(Debug, PartialEq, Eq)]
pub(crate) enum ExecutedToolCallsCheckpointError {
    OwnerMismatch,
    StatePoisoned,
    ResetPoisoned,
    Changed,
}

// The tool future owns this reservation, so completion or cancellation releases it.
pub(crate) struct DirectCallPermit {
    recording: Weak<()>,
    pending_direct_calls: Arc<AtomicUsize>,
    material_reset: Arc<Mutex<CancellationToken>>,
}

impl DirectCallPermit {
    pub(crate) fn strong_count(&self) -> usize {
        self.recording.strong_count()
    }
}

impl Drop for DirectCallPermit {
    fn drop(&mut self) {
        // Drop takes only reset: it must never wait for the Option-state mutex.
        let mut reset = self
            .material_reset
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // Keep reset locked through the atomic update so a new checkpoint cannot
        // be minted between invalidation and this permit's one release.
        std::mem::replace(&mut *reset, CancellationToken::new()).cancel();
        self.pending_direct_calls.fetch_sub(1, Ordering::Relaxed);
        drop(reset);
    }
}

#[derive(Default)]
struct ExecutedToolCallRecorderState {
    // Disabling drops this lifetime, permanently invalidating prepared Direct records.
    recording: Arc<()>,
    cells: HashMap<CellId, RecordedCell>,
    output_cells: HashMap<String, CellId>,
    retained_calls: HashMap<(std::mem::Discriminant<ResponseItem>, String), RetainedToolCalls>,
    pending_nested_calls: usize,
    seen_ids: SeenIds,
    // Keep nested IDs separate so this conservative filter cannot change existing completeness.
    seen_nested_ids: SeenIds,
    can_prove_wait_completion: bool,
    pending_wrapper_origins: HashSet<String>,
}

/// Keep each output's calls and completion marker together through replay and pruning.
#[derive(Default)]
struct RetainedToolCalls {
    calls: Vec<ExecutedToolCall>,
    complete: bool,
    cell_id: Option<String>,
    runtime_cell_id: Option<CellId>,
    // Invocation IDs stay local and are retained only with their original output's calls.
    call_index_by_id: HashMap<String, usize>,
    // Track newly backfilled metadata separately from pre-existing observations.
    truncated_call_index_by_id: HashMap<String, usize>,
    late_truncated_indices: HashSet<usize>,
    result_metadata_updated: bool,
}

impl RetainedToolCalls {
    fn clear_late_truncated_metadata(&mut self) {
        for index in self.late_truncated_indices.drain() {
            if let Some(call) = self.calls.get_mut(index) {
                call.set_tool_result_metadata(ToolResultMetadata::default());
                self.result_metadata_updated = true;
            }
        }
        self.truncated_call_index_by_id.clear();
    }
}

#[derive(Default, PartialEq, Eq)]
enum CellCompletion {
    #[default]
    Unobserved,
    Recording,
    Incomplete,
    Complete,
}

#[derive(Default)]
struct RecordedCell {
    pending_calls: IndexMap<String, ExecutedToolCall>,
    pending_full_argument_bytes: usize,
    completion: CellCompletion,
    originating_call_id: Option<String>,
    truncated_metadata_binding_valid: bool,
    observed_truncated_call: bool,
    dispatch_closed: bool,
}

impl ExecutedToolCallRecorderState {
    fn invalidate_origin(&mut self, origin: &str) {
        self.pending_wrapper_origins.remove(origin);
        for cell in self.cells.values_mut() {
            if cell.originating_call_id.as_deref() == Some(origin) {
                cell.completion = CellCompletion::Incomplete;
                cell.truncated_metadata_binding_valid = false;
            }
        }
        for ((_, output_id), retained) in &mut self.retained_calls {
            if output_id == origin || retained.cell_id.as_deref() == Some(origin) {
                retained.complete = false;
                retained.clear_late_truncated_metadata();
            }
        }
    }

    // A successful callback consumes the freshness observed at wrapper submission.
    fn observe_cell_origin(&mut self, origin: &str) -> bool {
        let fresh =
            self.pending_wrapper_origins.remove(origin) || self.seen_ids.observe_call_id(origin);
        if !fresh {
            self.invalidate_origin(origin);
        }
        fresh
    }

    fn invalidate_cell(&mut self, cell_id: &CellId) {
        if let Some(cell) = self.cells.get_mut(cell_id) {
            cell.completion = CellCompletion::Incomplete;
            cell.truncated_metadata_binding_valid = false;
        }
        for retained in self.retained_calls.values_mut() {
            if retained.runtime_cell_id.as_ref() == Some(cell_id) {
                retained.complete = false;
                retained.clear_late_truncated_metadata();
            }
        }
    }

    fn register_cell(&mut self, cell_id: &CellId, output_call_id: &str) {
        if self.output_cells.len() >= MAX_PENDING_EXECUTED_TOOL_CALLS {
            // Ended empty cells can leave mappings without any records to attach.
            // Reclaim those only under pressure, preserving late partial records otherwise.
            self.output_cells
                .retain(|_, cell_id| self.cells.contains_key(cell_id));
        }
        loop {
            let needs_cell_slot = self.cells.len() >= MAX_PENDING_EXECUTED_TOOL_CALLS
                && !self.cells.contains_key(cell_id);
            if !needs_cell_slot && self.pending_nested_calls < MAX_PENDING_EXECUTED_TOOL_CALLS {
                break;
            }

            let output_cells = self.output_cells.values().collect::<HashSet<_>>();
            let finished_cell = self.cells.iter().find_map(|(id, cell)| {
                // Preserve late records until pressure, and never discard the cell
                // whose output is about to make those records attachable again.
                // Empty cells can free cell slots, but not pending-call slots.
                (id != cell_id
                    && (needs_cell_slot || !cell.pending_calls.is_empty())
                    && matches!(
                        cell.completion,
                        CellCompletion::Complete | CellCompletion::Incomplete
                    )
                    && !output_cells.contains(id))
                .then(|| (id.clone(), cell.pending_calls.len()))
            });
            let Some((id, pending_calls)) = finished_cell else {
                break;
            };
            self.invalidate_cell(&id);
            self.cells.remove(&id);
            self.pending_nested_calls = self.pending_nested_calls.saturating_sub(pending_calls);
        }
        if (self.cells.len() >= MAX_PENDING_EXECUTED_TOOL_CALLS
            && !self.cells.contains_key(cell_id))
            || (self.output_cells.len() >= MAX_PENDING_EXECUTED_TOOL_CALLS
                && !self.output_cells.contains_key(output_call_id))
        {
            return;
        }
        self.cells
            .entry(cell_id.clone())
            .or_default()
            .originating_call_id
            .get_or_insert_with(|| output_call_id.to_string());
        self.output_cells
            .insert(output_call_id.to_string(), cell_id.clone());
    }
}

impl ExecutedToolCalls {
    pub(crate) fn new(features: &Features, history: &InitialHistory) -> Self {
        Self {
            state: Arc::new(Mutex::new(Self::is_enabled(features).then(|| {
                ExecutedToolCallRecorderState {
                    seen_ids: SeenIds::from_history(history),
                    // Runtime cell IDs can restart after resume/fork; inherited wait
                    // handles cannot be distinguished from newly allocated handles.
                    can_prove_wait_completion: matches!(
                        history,
                        InitialHistory::New | InitialHistory::Cleared
                    ),
                    ..Default::default()
                }
            }))),
            material_reset: Arc::new(Mutex::new(CancellationToken::new())),
            retained_direct_metadata_bytes: Arc::new(AtomicUsize::new(0)),
            pending_direct_calls: Arc::new(AtomicUsize::new(0)),
            mcp_attribution: mcp_attribution::McpAttributionRecorder::new(history),
        }
    }

    pub(crate) fn record_mcp_source(&self, source: McpAttributionSource) {
        self.mcp_attribution.record(source);
    }

    pub(crate) fn mcp_attribution_snapshot(&self) -> McpAttribution {
        self.mcp_attribution.snapshot()
    }

    pub(crate) fn mcp_attribution_checkpoint(&self, force: bool) -> Option<(McpAttribution, u64)> {
        self.mcp_attribution.checkpoint(force)
    }

    pub(crate) fn mark_mcp_attribution_persisted(&self, revision: u64) {
        self.mcp_attribution.mark_persisted(revision);
    }

    /// Captures Option-state and Direct reservation/permit lifetimes without enabling
    /// recording or visiting the ordinary lock seam. Disabled states retain ownership.
    pub(crate) fn state_checkpoint(
        &self,
    ) -> Result<ExecutedToolCallsCheckpoint, ExecutedToolCallsCheckpointError> {
        let _state_guard = self
            .state
            .lock()
            .map_err(|_| ExecutedToolCallsCheckpointError::StatePoisoned)?;
        let reset = self
            .material_reset
            .lock()
            .map_err(|_| ExecutedToolCallsCheckpointError::ResetPoisoned)?;
        Ok(ExecutedToolCallsCheckpoint {
            state_owner: Arc::downgrade(&self.state),
            reset_owner: Arc::downgrade(&self.material_reset),
            reset: reset.child_token(),
        })
    }

    pub(crate) fn verify_state_checkpoint(
        &self,
        checkpoint: &ExecutedToolCallsCheckpoint,
    ) -> Result<(), ExecutedToolCallsCheckpointError> {
        if !Weak::ptr_eq(&checkpoint.state_owner, &Arc::downgrade(&self.state))
            || !Weak::ptr_eq(
                &checkpoint.reset_owner,
                &Arc::downgrade(&self.material_reset),
            )
        {
            return Err(ExecutedToolCallsCheckpointError::OwnerMismatch);
        }
        let _state_guard = self
            .state
            .lock()
            .map_err(|_| ExecutedToolCallsCheckpointError::StatePoisoned)?;
        let _reset_guard = self
            .material_reset
            .lock()
            .map_err(|_| ExecutedToolCallsCheckpointError::ResetPoisoned)?;
        if checkpoint.reset.is_cancelled() {
            Err(ExecutedToolCallsCheckpointError::Changed)
        } else {
            Ok(())
        }
    }

    fn lock_state(&self) -> MutexGuard<'_, Option<ExecutedToolCallRecorderState>> {
        let state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut reset = self
            .material_reset
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // Cancel before any caller can read or mutate the returned native guard.
        // Read-only and no-op visits conservatively revoke too.
        std::mem::replace(&mut *reset, CancellationToken::new()).cancel();
        state
    }

    /// A later wait cannot claim a complete inventory if an earlier wire copy
    /// lost recorded calls or arguments from the same Code Mode cell.
    pub(crate) fn invalidate_wire_inventory_loss(
        &self,
        original: &[ResponseItem],
        bounded: &[ResponseItem],
    ) {
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return;
        };
        // Request bounding clones the same items in the same order; it only edits metadata.
        for (original, bounded) in original.iter().zip(bounded) {
            let Some(metadata) = original.executed_tool_call_metadata() else {
                continue;
            };
            let Some(origin) = metadata.cell_id.as_deref() else {
                continue;
            };
            let Some(calls) = metadata
                .executed_tool_calls
                .as_deref()
                .filter(|calls| !calls.is_empty())
            else {
                continue;
            };
            if bounded
                .executed_tool_call_metadata()
                .is_none_or(|bounded| !bounded.has_same_tool_calls(calls))
            {
                state.invalidate_origin(origin);
            }
        }
    }

    /// Called under the session config lock; this never changes execution features.
    pub(crate) fn refresh(&self, features: &Features) {
        let enabled = Self::is_enabled(features);
        let mut state = self.lock_state();
        if enabled != state.is_some() {
            *state = enabled.then(|| ExecutedToolCallRecorderState {
                seen_ids: SeenIds::unobserved_history(),
                ..Default::default()
            });
        }
    }

    /// The turn's feature policy is independent of whether this session has a recorder.
    pub(crate) fn is_enabled(features: &Features) -> bool {
        features.enabled(Feature::ExecutedToolCallMetadata)
    }

    pub(crate) fn record_tool_call(
        &self,
        call: &ToolCall,
        source: &ToolCallSource,
        step_context: &StepContext,
    ) {
        self.record_call(call, source, step_context.tool_router.tool_mode());
    }

    /// Keep a Direct record with its invocation so it can be attached to that invocation's output.
    pub(crate) fn prepare_direct_call(
        &self,
        call: &ToolCall,
        source: &ToolCallSource,
        step_context: &StepContext,
    ) -> Option<(ExecutedToolCall, DirectCallPermit)> {
        if is_code_mode_wrapper(call, source, step_context.tool_router.tool_mode()) {
            return None;
        }
        let permit = self.reserve_direct_call()?;
        let (mut recorded, _) = recorded_call(call);
        let argument_bytes = serialized_json_bytes(recorded.arguments()).unwrap_or(usize::MAX);
        if matches!(recorded.arguments(), ExecutedToolCallArguments::Raw(_))
            && argument_bytes > MAX_EXECUTED_TOOL_CALL_ARGUMENT_BYTES
        {
            recorded = ExecutedToolCall::truncated(
                recorded.name,
                argument_bytes,
                MAX_EXECUTED_TOOL_CALL_ARGUMENT_BYTES,
            );
        }
        Some((recorded, permit))
    }

    fn reserve_direct_call(&self) -> Option<DirectCallPermit> {
        let state = self.lock_state();
        let recording = Arc::downgrade(&state.as_ref()?.recording);
        self.pending_direct_calls
            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |pending| {
                (pending < MAX_PENDING_EXECUTED_TOOL_CALLS).then_some(pending + 1)
            })
            .ok()?;
        // Keep the state guard through reservation: capture uses state then reset.
        drop(state);
        Some(DirectCallPermit {
            recording,
            pending_direct_calls: Arc::clone(&self.pending_direct_calls),
            material_reset: Arc::clone(&self.material_reset),
        })
    }

    /// Validate the recording lifetime and attach together so a config refresh
    /// cannot invalidate the call between those two operations.
    pub(crate) fn attach_direct_call_to_output(
        &self,
        item: &mut ResponseItem,
        prepared: Option<(ExecutedToolCall, DirectCallPermit)>,
    ) {
        let Some((call, permit)) = prepared else {
            return;
        };
        let state = self.lock_state();
        let Some(state) = state.as_ref() else {
            return;
        };
        if !permit.recording.ptr_eq(&Arc::downgrade(&state.recording)) {
            return;
        }
        let complete = matches!(call.arguments(), ExecutedToolCallArguments::Raw(_));
        item.append_executed_tool_calls(vec![call]);
        if complete {
            item.mark_tool_calls_complete();
        }
        let retained = self.retained_direct_metadata_bytes.load(Ordering::Relaxed);
        let available = MAX_RETAINED_DIRECT_METADATA_BYTES.saturating_sub(retained);
        let mut bytes = executed_tool_call_metadata_bytes(item);
        let original_bytes = bytes;
        if bytes > available {
            item.retain_tool_resource_access_or_omit_metadata(bytes - available);
            bytes = executed_tool_call_metadata_bytes(item);
        }
        if bytes > available {
            item.omit_tool_result_metadata(bytes - available);
            bytes = executed_tool_call_metadata_bytes(item);
        }
        if bytes > available {
            item.clear_tool_result_metadata();
            bytes = executed_tool_call_metadata_bytes(item);
        }
        if bytes > available {
            item.clear_executed_tool_calls();
            metadata_metrics::record_shedding(
                "direct_retained",
                original_bytes,
                executed_tool_call_metadata_bytes(item),
                codex_otel::global().as_ref(),
            );
            return;
        }
        // All Direct attachments share the recorder lock, including cloned handles.
        self.retained_direct_metadata_bytes
            .store(retained + bytes, Ordering::Relaxed);
        metadata_metrics::record_shedding(
            "direct_retained",
            original_bytes,
            bytes,
            codex_otel::global().as_ref(),
        );
    }

    /// Remember IDs from response items that bypass local tool dispatch.
    pub(crate) fn observe_non_dispatched_call(&self, item: &ResponseItem) {
        let Some(call_id) = input_call_id(item) else {
            return;
        };
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return;
        };
        if !state.seen_ids.observe_call_id(call_id) {
            state.invalidate_origin(call_id);
        }
    }

    pub(crate) fn record_accepted_result(
        &self,
        source: &ToolCallSource,
        call_id: &str,
        result: &dyn ToolOutput,
    ) {
        if !matches!(source, ToolCallSource::CodeMode { .. }) {
            return;
        }
        // Release the lock before calling the output's trait method.
        let recording = self.lock_state().is_some();
        if recording && let Some(metadata) = result.tool_result_metadata() {
            self.record_tool_result_metadata(source, call_id, metadata);
        }
    }

    fn record_call(&self, call: &ToolCall, source: &ToolCallSource, tool_mode: ToolMode) {
        if self.lock_state().is_none() {
            return;
        }
        match source {
            ToolCallSource::Direct | ToolCallSource::DirectPlaintextMessage => {
                let mut state = self.lock_state();
                let Some(state) = state.as_mut() else {
                    return;
                };
                let fresh = state.seen_ids.observe_call_id(&call.call_id);
                if !fresh {
                    state.invalidate_origin(&call.call_id);
                }
                if fresh
                    && is_code_mode_wrapper(call, source, tool_mode)
                    && state.pending_wrapper_origins.len() < MAX_PENDING_EXECUTED_TOOL_CALLS
                {
                    state.pending_wrapper_origins.insert(call.call_id.clone());
                }
            }
            ToolCallSource::CodeMode { cell_id, .. } => {
                let (recorded_call, original_bytes) = recorded_call(call);
                self.record_nested_tool_call(
                    CellId::new(cell_id.clone()),
                    call.call_id.clone(),
                    recorded_call,
                    original_bytes,
                );
            }
        }
    }

    fn record_nested_tool_call(
        &self,
        cell_id: CellId,
        call_id: String,
        call: ExecutedToolCall,
        original_bytes: usize,
    ) {
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return;
        };
        let unique_nested_id = state.seen_nested_ids.observe_call_id(&call_id);
        if !unique_nested_id {
            for retained in state.retained_calls.values_mut() {
                if retained.truncated_call_index_by_id.contains_key(&call_id) {
                    retained.clear_late_truncated_metadata();
                }
            }
        }
        if state
            .cells
            .get(&cell_id)
            .is_none_or(|cell| cell.dispatch_closed)
        {
            state.invalidate_cell(&cell_id);
        }
        if state.pending_nested_calls > MAX_PENDING_EXECUTED_TOOL_CALLS
            || (state.cells.len() >= MAX_PENDING_EXECUTED_TOOL_CALLS
                && !state.cells.contains_key(&cell_id))
        {
            if let Some(cell) = state.cells.get_mut(&cell_id) {
                cell.completion = CellCompletion::Incomplete;
            }
            return;
        }
        let at_pending_call_limit = state.pending_nested_calls == MAX_PENDING_EXECUTED_TOOL_CALLS;
        let cell = state.cells.entry(cell_id).or_default();
        let duplicate_call_id = cell.pending_calls.contains_key(&call_id);
        if !unique_nested_id || duplicate_call_id {
            cell.truncated_metadata_binding_valid = false;
        }
        let max_bytes = MAX_EXECUTED_TOOL_CALL_ARGUMENT_BYTES.min(
            MAX_EXECUTED_TOOL_CALL_FULL_ARGUMENT_BYTES_PER_OUTPUT
                .saturating_sub(cell.pending_full_argument_bytes),
        );
        let call = if at_pending_call_limit {
            ExecutedToolCall::truncated(call.name, original_bytes, /*max_bytes*/ 0)
        } else if original_bytes <= max_bytes {
            cell.pending_full_argument_bytes = cell
                .pending_full_argument_bytes
                .saturating_add(original_bytes);
            call
        } else {
            ExecutedToolCall::truncated(call.name, original_bytes, max_bytes)
        };
        let truncated = matches!(
            call.arguments(),
            ExecutedToolCallArguments::Truncated { .. }
        );
        cell.observed_truncated_call |= truncated;
        cell.completion =
            if cell.completion == CellCompletion::Recording && !duplicate_call_id && !truncated {
                CellCompletion::Recording
            } else {
                CellCompletion::Incomplete
            };
        cell.pending_calls.insert(call_id, call);
        if !duplicate_call_id {
            state.pending_nested_calls += 1;
        }
    }

    fn record_tool_result_metadata(
        &self,
        source: &ToolCallSource,
        call_id: &str,
        metadata: &JsonValue,
    ) -> bool {
        let ToolCallSource::CodeMode { cell_id, .. } = source else {
            return false;
        };
        let metadata = ToolResultMetadata::new(metadata);
        let has_metadata = metadata.is_some();
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return false;
        };
        let call = state
            .cells
            .get_mut(&CellId::new(cell_id.clone()))
            .and_then(|cell| cell.pending_calls.get_mut(call_id));
        if let Some(call) = call {
            call.set_tool_result_metadata(metadata);
            return has_metadata;
        }
        let retained_call = state.retained_calls.values_mut().find_map(|retained| {
            if retained.runtime_cell_id.as_ref()?.as_str() != cell_id.as_str() {
                return None;
            }
            let index = *retained.call_index_by_id.get(call_id)?;
            Some((retained, index))
        });
        if let Some((retained, index)) = retained_call {
            // Older retry copies must not overwrite this output's accepted result metadata.
            retained.result_metadata_updated = true;
            retained.calls[index].set_tool_result_metadata(metadata);
            return has_metadata;
        }
        let mut candidates = state.retained_calls.values_mut().filter_map(|retained| {
            if retained.runtime_cell_id.as_ref()?.as_str() != cell_id.as_str() {
                return None;
            }
            let index = *retained.truncated_call_index_by_id.get(call_id)?;
            Some((retained, index))
        });
        let Some((retained, index)) = candidates.next() else {
            return false;
        };
        if candidates.next().is_some() {
            return false;
        }
        retained.late_truncated_indices.insert(index);
        retained.result_metadata_updated = true;
        retained.calls[index].set_tool_result_metadata(metadata);
        has_metadata
    }

    pub(crate) fn register_cell(&self, cell_id: &CellId, output_call_id: &str) {
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return;
        };
        if !state.observe_cell_origin(output_call_id) {
            state.invalidate_cell(cell_id);
        }
        state.register_cell(cell_id, output_call_id);
    }

    pub(crate) fn start_cell(&self, cell_id: &CellId, output_call_id: &str) {
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return;
        };
        let unique_cell = state.seen_ids.observe_runtime_cell_id(cell_id);
        let unique_origin = state.observe_cell_origin(output_call_id);
        if !unique_cell {
            state.invalidate_cell(cell_id);
            // A reused runtime ID cannot distinguish the old pending calls or
            // output mappings from this new execution. Do not attach them to it.
            if let Some(previous) = state.cells.remove(cell_id) {
                state.pending_nested_calls = state
                    .pending_nested_calls
                    .saturating_sub(previous.pending_calls.len());
            }
            state.output_cells.retain(|_, mapped| mapped != cell_id);
        }
        let history_ids_indexed = state.seen_ids.history_ids_indexed();
        state.register_cell(cell_id, output_call_id);
        if let Some(cell) = state.cells.get_mut(cell_id) {
            // Failed indexing must not make a known historical ID look fresh.
            cell.dispatch_closed = false;
            cell.truncated_metadata_binding_valid =
                unique_cell && unique_origin && history_ids_indexed;
            cell.completion = if unique_cell && unique_origin && history_ids_indexed {
                CellCompletion::Recording
            } else {
                CellCompletion::Incomplete
            };
        }
    }

    pub(crate) fn finish_cell_recording(&self, cell_id: &CellId) {
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            return;
        };
        // A closed cell may still be referenced by the final wait output. Keep its
        // original binding while late truncated results remain eligible for backfill.
        let has_retained_truncated_calls = state.retained_calls.values().any(|retained| {
            retained.runtime_cell_id.as_ref() == Some(cell_id)
                && !retained.truncated_call_index_by_id.is_empty()
        });
        if let Some(cell) = state.cells.get_mut(cell_id) {
            cell.dispatch_closed = true;
            match cell.completion {
                CellCompletion::Recording => {
                    // The closed dispatch gate makes this lossless inventory final, even if empty.
                    cell.completion = CellCompletion::Complete;
                }
                CellCompletion::Unobserved | CellCompletion::Incomplete => {
                    // Drop unverified cells only after emitting any partial records.
                    if cell.pending_calls.is_empty() && !has_retained_truncated_calls {
                        state.cells.remove(cell_id);
                    }
                }
                CellCompletion::Complete => {}
            }
        }
    }
}

fn is_code_mode_wrapper(call: &ToolCall, source: &ToolCallSource, tool_mode: ToolMode) -> bool {
    matches!(source, ToolCallSource::Direct)
        && matches!(tool_mode, ToolMode::CodeMode | ToolMode::CodeModeOnly)
        && call.tool_name.is_default_namespace()
        && matches!(
            (call.tool_name.name.as_str(), &call.payload),
            (
                crate::tools::code_mode::PUBLIC_TOOL_NAME,
                ToolPayload::Custom { .. }
            ) | (
                crate::tools::code_mode::WAIT_TOOL_NAME,
                ToolPayload::Function { .. }
            )
        )
}

fn recorded_call(call: &ToolCall) -> (ExecutedToolCall, usize) {
    let original_bytes = match &call.payload {
        ToolPayload::Function { arguments } => arguments.len(),
        ToolPayload::Custom { input } => serialized_json_bytes(input).unwrap_or(usize::MAX),
        ToolPayload::ToolSearch { arguments } => {
            serialized_json_bytes(arguments).unwrap_or(usize::MAX)
        }
    };
    let name = codex_tools::code_mode_name_for_tool_name(&call.tool_name);
    let recorded_call = if original_bytes > MAX_EXECUTED_TOOL_CALL_ARGUMENT_BYTES {
        ExecutedToolCall::truncated(name, original_bytes, MAX_EXECUTED_TOOL_CALL_ARGUMENT_BYTES)
    } else {
        let arguments = match &call.payload {
            ToolPayload::Function { arguments } => serde_json::from_str(arguments)
                .unwrap_or_else(|_| JsonValue::String(arguments.clone())),
            ToolPayload::Custom { input } => JsonValue::String(input.clone()),
            ToolPayload::ToolSearch { arguments } => {
                serde_json::to_value(arguments).unwrap_or_default()
            }
        };
        ExecutedToolCall::new(name, arguments)
    };
    (recorded_call, original_bytes)
}

fn input_call_id(item: &ResponseItem) -> Option<&str> {
    match item {
        ResponseItem::FunctionCall { call_id, .. }
        | ResponseItem::CustomToolCall { call_id, .. } => Some(call_id),
        ResponseItem::ToolSearchCall { call_id, .. }
        | ResponseItem::LocalShellCall { call_id, .. } => call_id.as_deref(),
        _ => None,
    }
}

fn output_call_id(item: &ResponseItem) -> Option<&str> {
    match item {
        ResponseItem::FunctionCallOutput { call_id, .. }
        | ResponseItem::ToolSearchOutput { call_id, .. } => call_id.as_deref(),
        ResponseItem::CustomToolCallOutput { call_id, .. } => Some(call_id),
        _ => None,
    }
}

//! Attaches host observations to request metadata and applies its byte budget.
//! Final request budgeting runs after the recorder lock is released; it never changes tool execution.

use super::*;

#[cfg(test)]
#[path = "sampling_checkpoint_tests.rs"]
mod sampling_checkpoint_tests;

#[derive(Clone, Copy, PartialEq, Eq)]
enum MetadataBudgetScope {
    AllCalls,
    CodeModeOnly,
}

impl ExecutedToolCalls {
    /// Attaches Code Mode observations while preserving Direct records captured in history.
    pub(crate) fn attach_to_compaction_prompt(&self, items: &mut [ResponseItem]) {
        let mut state = self.lock_state();
        let Some(state) = state.as_mut() else {
            clear_direct_call_metadata(items);
            return;
        };
        Self::attach_pending_to_prompt_with_state(
            state,
            items,
            &mut HashMap::new(),
            MetadataBudgetScope::CodeModeOnly,
        );
    }

    /// Attaches trusted completeness; request budgeting only revokes damaged inventories.
    pub(crate) fn attach_to_prompt(
        &self,
        items: &mut [ResponseItem],
        retry_cache: &mut ExecutedToolCallCache,
    ) {
        self.attach_to_prompt_inner(items, retry_cache, |_| ());
    }

    /// Captures after ordinary attachment; Option-state and genuine Direct reserve/Drop
    /// writers invalidate the returned checkpoint through their shared reset lifetime.
    /// This is not a complete atomic snapshot, MCP/final-byte owner or InputProof.
    pub(crate) fn attach_to_prompt_with_checkpoint(
        &self,
        items: &mut [ResponseItem],
        retry_cache: &mut ExecutedToolCallCache,
    ) -> Result<ExecutedToolCallsCheckpoint, ExecutedToolCallsCheckpointError> {
        self.attach_to_prompt_inner(items, retry_cache, |recorder| {
            if recorder.state.is_poisoned() {
                return Err(ExecutedToolCallsCheckpointError::StatePoisoned);
            }
            let reset = recorder
                .material_reset
                .lock()
                .map_err(|_| ExecutedToolCallsCheckpointError::ResetPoisoned)?;
            Ok(ExecutedToolCallsCheckpoint {
                state_owner: Arc::downgrade(&recorder.state),
                reset_owner: Arc::downgrade(&recorder.material_reset),
                reset: reset.child_token(),
            })
        })
    }

    fn attach_to_prompt_inner<T>(
        &self,
        items: &mut [ResponseItem],
        retry_cache: &mut ExecutedToolCallCache,
        after_attachment: impl FnOnce(&Self) -> T,
    ) -> T {
        let (attached, checkpoint) = {
            let mut state = self.lock_state();
            let attached = state.as_mut().map(|state| {
                Self::attach_pending_to_prompt_with_state(
                    state,
                    items,
                    retry_cache,
                    MetadataBudgetScope::AllCalls,
                )
            });
            // The same guard excludes intervening Option-state writers only.
            // Reset-only Direct Drop may run concurrently and invalidate its shared
            // reset lifetime; attachment does not read the pending Direct counter.
            (attached, after_attachment(self))
        };
        let Some(attached) = attached else {
            // Direct records now live in history; disabling capture also stops replaying them.
            clear_direct_call_metadata(items);
            return checkpoint;
        };
        if attached || items.iter().any(has_direct_call_metadata) {
            metadata_metrics::bound_prompt_metadata(
                items,
                bound_executed_tool_calls_for_prompt,
                "request",
                codex_otel::global().as_ref(),
            );
        }
        checkpoint
    }

    fn attach_pending_to_prompt_with_state(
        state: &mut ExecutedToolCallRecorderState,
        items: &mut [ResponseItem],
        retry_cache: &mut ExecutedToolCallCache,
        budget_scope: MetadataBudgetScope,
    ) -> bool {
        // Failed wrappers have no callback; only their bounded bitmap observation survives.
        state.pending_wrapper_origins.clear();
        if state.output_cells.is_empty()
            && state.retained_calls.is_empty()
            && retry_cache.is_empty()
        {
            return false;
        }

        let mut output_counts = HashMap::new();
        let mut input_indices = HashMap::new();
        for (index, item) in items.iter().enumerate() {
            if let Some(call_id) = output_call_id(item) {
                *output_counts.entry(call_id.to_string()).or_insert(0_usize) += 1;
            }
            if let Some(call_id) = input_call_id(item) {
                input_indices
                    .entry(call_id.to_string())
                    .and_modify(|entry: &mut Option<usize>| *entry = None)
                    .or_insert(Some(index));
            }
        }

        let has_truncated_bindings = state
            .retained_calls
            .values()
            .any(|retained| !retained.truncated_call_index_by_id.is_empty())
            || state.cells.values().any(|cell| {
                cell.truncated_metadata_binding_valid
                    && cell.pending_calls.values().any(|call| {
                        matches!(
                            call.arguments(),
                            ExecutedToolCallArguments::Truncated { .. }
                        ) && !call.has_tool_result_metadata()
                    })
            });
        if has_truncated_bindings {
            // A conflicting sibling output invalidates the new late backfill too.
            // Check every known output before cloning any retained calls into this request.
            let mut untrusted_cells = HashSet::new();
            for (index, item) in items.iter().enumerate() {
                let Some(call_id) = output_call_id(item) else {
                    continue;
                };
                let key = (std::mem::discriminant(item), call_id.to_string());
                let retained = state.retained_calls.get(&key);
                let binding = retained
                    .and_then(|retained| {
                        Some((
                            retained.runtime_cell_id.as_ref()?,
                            retained.cell_id.as_deref()?,
                            true,
                        ))
                    })
                    .or_else(|| {
                        let cell_id = state.output_cells.get(call_id)?;
                        let origin = state.cells.get(cell_id)?.originating_call_id.as_deref()?;
                        Some((cell_id, origin, false))
                    });
                let Some((cell_id, origin, previously_retained)) = binding else {
                    continue;
                };
                let empty_inventory = item.executed_tool_call_metadata().is_none_or(|metadata| {
                    metadata.executed_tool_calls.is_none() && metadata.cell_id.is_none()
                });
                let matches_input = match input_indices.get(call_id) {
                    None => previously_retained,
                    Some(input_index) => input_index.is_some_and(|input_index| {
                        input_index < index
                            && code_mode_input_matches_output(
                                &items[input_index],
                                item,
                                origin,
                                cell_id,
                            )
                    }),
                };
                let matches_retry = retained.is_none_or(|retained| {
                    retry_cache
                        .get(&key)
                        .filter(|_| !retained.result_metadata_updated)
                        .is_none_or(|cached| {
                            cached.len() == retained.calls.len()
                                && cached.iter().zip(&retained.calls).all(|(cached, current)| {
                                    cached.name == current.name
                                        && cached.arguments() == current.arguments()
                                })
                        })
                });
                if output_counts.get(call_id) != Some(&1)
                    || !matches_input
                    || !empty_inventory
                    || !matches_retry
                {
                    untrusted_cells.insert(cell_id.clone());
                }
            }
            for cell_id in &untrusted_cells {
                if let Some(cell) = state.cells.get_mut(cell_id) {
                    cell.truncated_metadata_binding_valid = false;
                }
            }
            for retained in state.retained_calls.values_mut() {
                if retained
                    .runtime_cell_id
                    .as_ref()
                    .is_some_and(|id| untrusted_cells.contains(id))
                {
                    retained.clear_late_truncated_metadata();
                }
            }
        }

        // Updated records supersede older retry snapshots.
        retry_cache.retain(|key, _| {
            !state
                .retained_calls
                .get(key)
                .is_some_and(|retained| retained.result_metadata_updated)
        });
        let mut pending_outputs = retry_cache
            .keys()
            .chain(state.retained_calls.keys())
            .cloned()
            .collect::<HashSet<_>>();
        let mut attached = false;
        for index in (0..items.len()).rev() {
            if state.output_cells.is_empty() && pending_outputs.is_empty() {
                break;
            }
            let item = &items[index];
            if has_direct_call_metadata(item) {
                continue;
            }
            let Some(call_id) = output_call_id(item) else {
                continue;
            };
            let key = (std::mem::discriminant(item), call_id.to_string());
            let retained = state.retained_calls.get(&key);
            let mut complete = retained.is_some_and(|retained| retained.complete);
            let mut cell_id = retained.and_then(|retained| retained.cell_id.clone());
            let calls = if let Some(cached) =
                retry_cache.get(&key).or_else(|| retained.map(|r| &r.calls))
            {
                if !pending_outputs.remove(&key) {
                    continue;
                }
                cached.clone()
            } else {
                let mut runtime_cell_id = None;
                let mut calls = Vec::new();
                let mut call_index_by_id = HashMap::new();
                let mut truncated_call_index_by_id = HashMap::new();
                if let Some(output_cell_id) = state.output_cells.remove(call_id)
                    && let Some(cell) = state.cells.get_mut(&output_cell_id)
                {
                    cell_id = cell.originating_call_id.clone();
                    runtime_cell_id = Some(output_cell_id.clone());
                    // Validate the first delta too: a later wait cannot repair a
                    // missing or ambiguous exec/output association.
                    let matches_input =
                        input_indices
                            .get(call_id)
                            .copied()
                            .flatten()
                            .is_some_and(|input_index| {
                                input_index < index
                                    && cell_id.as_deref().is_some_and(|origin| {
                                        code_mode_input_matches_output(
                                            &items[input_index],
                                            item,
                                            origin,
                                            &output_cell_id,
                                        )
                                    })
                            });
                    let valid_output = output_counts.get(call_id) == Some(&1) && matches_input;
                    if !valid_output {
                        cell.completion = CellCompletion::Incomplete;
                        cell.truncated_metadata_binding_valid = false;
                    }
                    let pending_calls = cell.pending_calls.len();
                    for (call_id, call) in cell.pending_calls.drain(..) {
                        if matches!(call.arguments(), ExecutedToolCallArguments::Raw(_)) {
                            call_index_by_id.insert(call_id, calls.len());
                        } else if cell.truncated_metadata_binding_valid
                            && !call.has_tool_result_metadata()
                        {
                            truncated_call_index_by_id.insert(call_id, calls.len());
                        }
                        calls.push(call);
                    }
                    cell.pending_full_argument_bytes = 0;
                    complete = cell.completion == CellCompletion::Complete
                        && (state.can_prove_wait_completion
                            || matches!(item, ResponseItem::CustomToolCallOutput { .. }));
                    let has_retained_truncated_calls =
                        state.retained_calls.values().any(|retained| {
                            retained.runtime_cell_id.as_ref() == Some(&output_cell_id)
                                && !retained.truncated_call_index_by_id.is_empty()
                        });
                    let keep_truncated_binding = cell.truncated_metadata_binding_valid
                        && cell.observed_truncated_call
                        && (!cell.dispatch_closed
                            || !truncated_call_index_by_id.is_empty()
                            || has_retained_truncated_calls);
                    if matches!(
                        cell.completion,
                        CellCompletion::Complete | CellCompletion::Incomplete
                    ) && !keep_truncated_binding
                    {
                        // Retain the original binding while a live cell can dispatch or
                        // a closed cell still has results eligible for late backfill.
                        state.cells.remove(&output_cell_id);
                    }
                    state.pending_nested_calls =
                        state.pending_nested_calls.saturating_sub(pending_calls);
                    state
                        .output_cells
                        .retain(|_, registered_cell_id| registered_cell_id != &output_cell_id);
                }
                if calls.is_empty() && !complete {
                    continue;
                }
                retry_cache.insert(key.clone(), calls.clone());
                state.retained_calls.insert(
                    key,
                    RetainedToolCalls {
                        calls: calls.clone(),
                        complete,
                        cell_id: cell_id.clone(),
                        runtime_cell_id,
                        call_index_by_id,
                        truncated_call_index_by_id,
                        late_truncated_indices: HashSet::new(),
                        result_metadata_updated: false,
                    },
                );
                calls
            };
            let item = &mut items[index];
            item.append_executed_tool_calls(calls);
            if let Some(cell_id) = cell_id {
                item.set_tool_call_cell_id(&cell_id);
            }
            if complete {
                item.mark_tool_calls_complete();
            } else {
                item.clear_tool_calls_complete();
            }
            attached = true;
        }
        // Compaction may retry with a shortened history without installing that history.
        // Keep absent observations until a normal sampling request confirms the live window.
        if budget_scope == MetadataBudgetScope::AllCalls && !pending_outputs.is_empty() {
            state
                .retained_calls
                .retain(|key, _| !pending_outputs.contains(key));
        }
        let mut invalid_cells = HashSet::new();
        for index in 0..items.len() {
            let item = &items[index];
            if has_direct_call_metadata(item) {
                continue;
            }
            let Some(call_id) = output_call_id(item) else {
                continue;
            };
            let key = (std::mem::discriminant(item), call_id.to_string());
            let Some(retained) = state.retained_calls.get_mut(&key) else {
                continue;
            };
            let matches_inventory = item.executed_tool_call_metadata().is_some_and(|metadata| {
                metadata.cell_id == retained.cell_id
                    && (metadata.has_same_tool_calls(&retained.calls)
                        || (retained.calls.is_empty() && metadata.executed_tool_calls.is_none()))
            });
            // A verified output may outlive its input after compaction. Any input
            // still present must continue to identify the same exec or wait.
            let matches_input = input_indices.get(call_id).is_none_or(|input_index| {
                input_index.is_some_and(|input_index| {
                    input_index < index
                        && match (&retained.cell_id, &retained.runtime_cell_id) {
                            (Some(origin), Some(runtime_cell)) => code_mode_input_matches_output(
                                &items[input_index],
                                item,
                                origin,
                                runtime_cell,
                            ),
                            _ => true,
                        }
                })
            });
            // Lost or ambiguous evidence cannot become complete again on a retry.
            let intact =
                output_counts.get(call_id) == Some(&1) && matches_inventory && matches_input;
            retained.complete &= intact;
            if !intact && let Some(cell) = retained.runtime_cell_id.clone() {
                invalid_cells.insert(cell);
            }
        }
        for cell_id in &invalid_cells {
            if let Some(cell) = state.cells.get_mut(cell_id) {
                cell.completion = CellCompletion::Incomplete;
                cell.truncated_metadata_binding_valid = false;
            }
        }
        if !invalid_cells.is_empty() {
            for retained in state.retained_calls.values_mut() {
                if retained
                    .runtime_cell_id
                    .as_ref()
                    .is_some_and(|cell_id| invalid_cells.contains(cell_id))
                {
                    retained.complete = false;
                    retained.clear_late_truncated_metadata();
                }
            }
        }
        for item in items.iter_mut() {
            if has_direct_call_metadata(item) {
                continue;
            }
            let Some(call_id) = output_call_id(item) else {
                continue;
            };
            let key = (std::mem::discriminant(&*item), call_id.to_string());
            let Some(retained) = state.retained_calls.get(&key) else {
                continue;
            };
            if retained.complete {
                item.mark_tool_calls_complete();
            } else {
                item.clear_tool_calls_complete();
            }
        }

        let metadata_bytes = items
            .iter()
            .filter(|item| {
                budget_scope == MetadataBudgetScope::AllCalls || !has_direct_call_metadata(item)
            })
            .fold(0_usize, |bytes, item| {
                bytes.saturating_add(executed_tool_call_metadata_bytes(item))
            });
        if metadata_bytes > MAX_EXECUTED_TOOL_CALL_FULL_ARGUMENT_BYTES_PER_OUTPUT {
            match budget_scope {
                MetadataBudgetScope::AllCalls => {
                    metadata_metrics::bound_prompt_metadata(
                        items,
                        bound_executed_tool_calls_for_prompt_prioritizing_recent,
                        "retained",
                        codex_otel::global().as_ref(),
                    );
                }
                MetadataBudgetScope::CodeModeOnly => {
                    // Validate bindings against the complete history above, but do not make
                    // captured Direct records compete with Code Mode's bounded recorder.
                    let (indices, mut bounded): (Vec<_>, Vec<_>) = items
                        .iter()
                        .enumerate()
                        .filter(|(_, item)| {
                            !has_direct_call_metadata(item)
                                && item.executed_tool_call_metadata().is_some()
                        })
                        .map(|(index, item)| (index, item.clone()))
                        .unzip();
                    metadata_metrics::bound_prompt_metadata(
                        &mut bounded,
                        bound_executed_tool_calls_for_prompt_prioritizing_recent,
                        "compaction",
                        codex_otel::global().as_ref(),
                    );
                    for (index, item) in indices.into_iter().zip(bounded) {
                        items[index] = item;
                    }
                }
            }
            let retained_before_bounding = std::mem::take(&mut state.retained_calls);
            let mut bounded_outputs = HashSet::new();
            for item in items.iter_mut() {
                if has_direct_call_metadata(item) {
                    continue;
                }
                let Some(call_id) = output_call_id(item) else {
                    continue;
                };
                let key = (std::mem::discriminant(&*item), call_id.to_string());
                // History already carries unmanaged records; retaining them would append them again.
                let Some(previous) = retained_before_bounding.get(&key) else {
                    continue;
                };
                let metadata = item.executed_tool_call_metadata();
                let unique_output = bounded_outputs.insert(key.clone());
                if !unique_output && let Some(retained) = state.retained_calls.get_mut(&key) {
                    retained.call_index_by_id.clear();
                    retained.clear_late_truncated_metadata();
                }
                if let Some(runtime_cell_id) = &previous.runtime_cell_id
                    && metadata
                        .is_none_or(|metadata| !metadata.has_same_tool_calls(&previous.calls))
                    && let Some(cell) = state.cells.get_mut(runtime_cell_id)
                {
                    cell.completion = CellCompletion::Incomplete;
                }
                if let Some(metadata) = metadata
                    && (metadata
                        .executed_tool_calls
                        .as_ref()
                        .is_some_and(|calls| !calls.is_empty())
                        || metadata.tool_calls_complete.is_some())
                {
                    // Metadata-only shedding preserves slots; changed calls or duplicate outputs do not.
                    let same_calls = unique_output && metadata.has_same_tool_calls(&previous.calls);
                    let call_index_by_id = if same_calls {
                        previous.call_index_by_id.clone()
                    } else {
                        HashMap::new()
                    };
                    let retained = state.retained_calls.entry(key).or_default();
                    retained.runtime_cell_id = previous.runtime_cell_id.clone();
                    retained.calls = metadata.executed_tool_calls.clone().unwrap_or_default();
                    if let Some(cell_id) = metadata.cell_id.as_ref() {
                        retained.cell_id = Some(cell_id.clone());
                    }
                    retained.complete |= metadata.tool_calls_complete == Some(true);
                    retained.call_index_by_id = call_index_by_id;
                    // Budgeting preserves call order; changed inventories lose their indices.
                    if same_calls {
                        retained.truncated_call_index_by_id =
                            previous.truncated_call_index_by_id.clone();
                        retained.late_truncated_indices = previous.late_truncated_indices.clone();
                    } else {
                        // The budgeter never reorders calls. Remove only the new late
                        // evidence before losing the indices that identify it.
                        for index in &previous.late_truncated_indices {
                            if let Some(call) = retained.calls.get_mut(*index) {
                                call.set_tool_result_metadata(ToolResultMetadata::default());
                            }
                        }
                    }
                    retained.result_metadata_updated = previous.result_metadata_updated;
                }
            }
            if budget_scope == MetadataBudgetScope::CodeModeOnly {
                state.retained_calls.extend(
                    retained_before_bounding
                        .into_iter()
                        .filter(|(key, _)| pending_outputs.contains(key)),
                );
            }
        }

        attached
    }
}

// Direct records already belong to their output; never rebuild them from the Code Mode cache.
fn clear_direct_call_metadata(items: &mut [ResponseItem]) {
    for item in items
        .iter_mut()
        .filter(|item| has_direct_call_metadata(item))
    {
        item.clear_executed_tool_calls();
    }
}

fn has_direct_call_metadata(item: &ResponseItem) -> bool {
    item.executed_tool_call_metadata().is_some_and(|metadata| {
        metadata.cell_id.is_none() && metadata.executed_tool_calls.is_some()
    })
}

fn code_mode_input_matches_output(
    input: &ResponseItem,
    output: &ResponseItem,
    origin: &str,
    runtime_cell: &CellId,
) -> bool {
    match (input, output) {
        (
            ResponseItem::CustomToolCall {
                name,
                namespace,
                call_id,
                ..
            },
            ResponseItem::CustomToolCallOutput { .. },
        ) => {
            call_id == origin
                && crate::tools::code_mode::is_exec_tool_name(&codex_tools::ToolName::new(
                    namespace.clone(),
                    name,
                ))
        }
        (
            ResponseItem::FunctionCall {
                name,
                namespace,
                call_id,
                arguments,
                ..
            },
            ResponseItem::FunctionCallOutput { .. },
        ) => {
            call_id != origin
                && name == crate::tools::code_mode::WAIT_TOOL_NAME
                && codex_tools::ToolName::new(namespace.clone(), name).is_default_namespace()
                && serde_json::from_str::<JsonValue>(arguments).is_ok_and(|arguments| {
                    arguments.get("cell_id").and_then(JsonValue::as_str)
                        == Some(runtime_cell.as_str())
                })
        }
        _ => false,
    }
}

#[cfg(test)]
#[path = "request_metadata_tests.rs"]
mod tests;

//! Direct pending lifetimes only; no tool dispatch, provider, InputProof or sender.
//! The prepared tuple comes from the same native preparation API as Direct regressions.

use std::panic::AssertUnwindSafe;
use std::panic::catch_unwind;
use std::sync::Barrier;
use std::sync::mpsc::sync_channel;
use std::time::Duration;

use codex_protocol::models::FunctionCallOutputPayload;
use codex_protocol::models::ResponseInputItem;
use pretty_assertions::assert_eq;
use serde_json::json;

use super::*;

fn enabled_recorder() -> ExecutedToolCalls {
    let mut features = Features::default();
    features.enable(Feature::ExecutedToolCallMetadata);
    ExecutedToolCalls::new(&features, &InitialHistory::New)
}

async fn prepared_direct_call() -> (ExecutedToolCalls, (ExecutedToolCall, DirectCallPermit)) {
    let (_, turn) = crate::session::tests::make_session_and_context().await;
    let step = StepContext::for_test(Arc::new(turn));
    let recorder = enabled_recorder();
    let call = ToolCall {
        tool_name: codex_tools::ToolName::plain("test_tool"),
        call_id: "direct-checkpoint".to_string(),
        payload: ToolPayload::Function {
            arguments: json!({"argument": "kept"}).to_string(),
        },
        encrypted_function_args: None,
    };
    let prepared = recorder
        .prepare_direct_call(&call, &ToolCallSource::Direct, &step)
        .expect("native Direct metadata slot");
    (recorder, prepared)
}

fn assert_released_and_changed(
    recorder: &ExecutedToolCalls,
    checkpoint: &ExecutedToolCallsCheckpoint,
) {
    assert_eq!(recorder.pending_direct_calls.load(Ordering::Relaxed), 0);
    assert_eq!(
        recorder.verify_state_checkpoint(checkpoint),
        Err(ExecutedToolCallsCheckpointError::Changed),
    );
    let current = recorder.state_checkpoint().expect("current checkpoint");
    assert_eq!(recorder.verify_state_checkpoint(&current), Ok(()));
}

#[test]
fn direct_pending_count_revert_does_not_revive_checkpoint() {
    let recorder = enabled_recorder();
    let original = recorder
        .state_checkpoint()
        .expect("zero-pending checkpoint");
    let permit = recorder.reserve_direct_call().expect("real reservation");
    assert_eq!(recorder.pending_direct_calls.load(Ordering::Relaxed), 1);
    let reserved = recorder.state_checkpoint().expect("reserved checkpoint");
    assert_eq!(recorder.verify_state_checkpoint(&reserved), Ok(()));
    drop(permit);
    assert_released_and_changed(&recorder, &original);
    assert_released_and_changed(&recorder, &reserved);
}

#[tokio::test]
async fn unpolled_direct_future_drop_releases_once_and_revokes_checkpoint() {
    let (recorder, prepared) = prepared_direct_call().await;
    let checkpoint = recorder.state_checkpoint().expect("prepared checkpoint");
    let unpolled = async move {
        std::future::pending::<()>().await;
        drop(prepared);
    };
    assert_eq!(recorder.pending_direct_calls.load(Ordering::Relaxed), 1);
    drop(unpolled);
    assert_released_and_changed(&recorder, &checkpoint);
}

#[tokio::test]
async fn started_direct_future_abort_releases_once_and_revokes_checkpoint() {
    let (recorder, prepared) = prepared_direct_call().await;
    let (started_tx, started_rx) = tokio::sync::oneshot::channel();
    let task = tokio::spawn(async move {
        let held = prepared;
        started_tx.send(()).expect("observer must remain alive");
        std::future::pending::<()>().await;
        drop(held);
    });
    tokio::time::timeout(Duration::from_secs(5), started_rx)
        .await
        .expect("owned future must start")
        .expect("owned future must report start");
    let checkpoint = recorder.state_checkpoint().expect("started checkpoint");
    assert_eq!(recorder.pending_direct_calls.load(Ordering::Relaxed), 1);
    task.abort();
    let error = tokio::time::timeout(Duration::from_secs(5), task)
        .await
        .expect("owned abort must finish")
        .expect_err("aborted future must not complete normally");
    assert!(error.is_cancelled());
    assert_released_and_changed(&recorder, &checkpoint);
}

#[test]
fn old_direct_permit_drop_revokes_disabled_sampling_checkpoint() {
    let recorder = enabled_recorder();
    let permit = recorder.reserve_direct_call().expect("real reservation");
    recorder.refresh(&Features::default());
    let mut enabled = Features::default();
    enabled.enable(Feature::ExecutedToolCallMetadata);
    recorder.refresh(&enabled);
    recorder.refresh(&Features::default());
    assert_eq!(permit.strong_count(), 0);
    assert_eq!(recorder.pending_direct_calls.load(Ordering::Relaxed), 1);

    let mut items = vec![ResponseItem::from(ResponseInputItem::FunctionCallOutput {
        call_id: "direct-checkpoint".to_string(),
        output: FunctionCallOutputPayload::from_text("ordinary output".to_string()),
    })];
    let original = serde_json::to_value(&items).expect("ordinary output oracle");
    let mut cache = HashMap::new();
    let checkpoint = recorder
        .attach_to_prompt_with_checkpoint(&mut items, &mut cache)
        .expect("real disabled sampling attachment");
    assert!(recorder.state.lock().expect("ordinary state").is_none());
    assert_eq!(recorder.verify_state_checkpoint(&checkpoint), Ok(()));
    assert_eq!(
        serde_json::to_value(&items).expect("ordinary output preserved"),
        original,
    );
    assert!(cache.is_empty());

    drop(permit);
    assert_released_and_changed(&recorder, &checkpoint);
    assert!(recorder.state.lock().expect("still disabled").is_none());
}

#[test]
fn direct_drop_completes_without_waiting_for_state() {
    let recorder = enabled_recorder();
    let permit = recorder.reserve_direct_call().expect("real reservation");
    let checkpoint = recorder.state_checkpoint().expect("prepared checkpoint");
    let ready = Arc::new(Barrier::new(2));
    let worker_ready = Arc::clone(&ready);
    let (completed_tx, completed_rx) = sync_channel(0);
    // Spawn before taking either mutex: a failed spawn cannot unwind a permit
    // on this thread while it owns the reset guard.
    let worker = std::thread::spawn(move || {
        worker_ready.wait();
        drop(permit);
        completed_tx.send(()).expect("observer must remain alive");
    });

    let state = recorder.state.lock().expect("ordinary state guard");
    let reset = recorder
        .material_reset
        .lock()
        .expect("ordinary reset guard");
    ready.wait();
    drop(reset);
    // Only completion while state remains held is observed here. The barrier
    // does not establish when the worker entered Drop or prove reset serialization.
    let completed = completed_rx.recv_timeout(Duration::from_secs(5));
    // Always unlock state before any assertion or join. A broken Drop that takes
    // state must cause a bounded failure, not hang cleanup while state is held.
    drop(state);
    completed.expect("Drop must finish while the Option-state mutex remains held");
    worker.join().expect("owned Drop worker must finish");
    assert_released_and_changed(&recorder, &checkpoint);
}

#[test]
fn direct_drop_recovers_poisoned_reset_without_authenticating_it() {
    let recorder = enabled_recorder();
    let permit = recorder.reserve_direct_call().expect("real reservation");
    let checkpoint = recorder.state_checkpoint().expect("prepared checkpoint");
    let reset_owner = Arc::clone(&recorder.material_reset);
    assert!(
        catch_unwind(AssertUnwindSafe(move || {
            // This closure owns only reset, never a permit that could be dropped
            // recursively while panic unwinding still holds this mutex.
            let _reset = reset_owner.lock().expect("unpoisoned setup");
            panic!("poison Direct reset");
        }))
        .is_err()
    );
    assert!(catch_unwind(AssertUnwindSafe(|| drop(permit))).is_ok());
    assert_eq!(recorder.pending_direct_calls.load(Ordering::Relaxed), 0);
    assert!(checkpoint.reset.is_cancelled());
    assert!(recorder.material_reset.is_poisoned());
    assert!(matches!(
        recorder.state_checkpoint(),
        Err(ExecutedToolCallsCheckpointError::ResetPoisoned),
    ));
    assert_eq!(
        recorder.verify_state_checkpoint(&checkpoint),
        Err(ExecutedToolCallsCheckpointError::ResetPoisoned),
    );
}
